const migrationWeeks=['Inventory pages, news, events, research, images, files and portal resources.','Agree what moves, stays, is archived or retired; map fields and old URLs.','Prepare a representative import and confirm media / content mapping.','Review the pilot for formatting, files, categories, links and visibility.','Move approved content in batches and track completed / failed items.','Migrate agreed portal resources and check protected access; align the first microsite.','Reconcile content relationships and transfer remaining approved batches.','Review the migrated inventory with editors; record gaps before QA.','Compare source and destination counts; verify images, files, links and permissions.','Fix migration defects and re-check content against the agreed inventory.','Agree content freeze or delta sync; rehearse backups and rollback.','Run the final transfer, smoke-test migrated journeys and record acceptance.'];
const focus=document.querySelector('#migration-focus');focus.className='migration-focus';focus.innerHTML='<div class="focus-track"><span class="focus-icon">'+icon('search')+'</span><div><span class="kicker">EVERY PHASE / SEO</span><h3>Keep your work discoverable.</h3><p>Plan the URLs, build search-ready pages, preserve valuable links and verify launch settings.</p><div class="focus-steps">'+[['Baseline',0],['Build',2],['Redirects',4],['Validate',8],['Monitor',11]].map(([t,w])=>'<button data-focus-week="'+w+'">'+t+'</button>').join('')+'</div></div></div><div class="focus-track"><span class="focus-icon">'+icon('folder')+'</span><div><span class="kicker">EVERY PHASE / CONTENT MIGRATION</span><h3>Move the content. Verify it.</h3><p>Pages, news, events, research, images, files and agreed member resources—all tracked against an approved inventory.</p><div class="focus-steps">'+[['Inventory',0],['Pilot',2],['Transfer',4],['Reconcile',8],['Cutover',11]].map(([t,w])=>'<button data-focus-week="'+w+'">'+t+'</button>').join('')+'</div></div></div><p class="migration-boundary">'+icon('check')+' The migration inventory defines completeness. Volume, exports, archive decisions and backend dependencies are agreed before fixing the delivery baseline.</p>';document.querySelectorAll('[data-focus-week]').forEach(b=>b.onclick=()=>{pickWeek(Number(b.dataset.focusWeek));document.querySelector('.stage-panel').scrollIntoView({block:'start',behavior:'smooth'})});
const migrationDetail=document.createElement('div');migrationDetail.className='week-migration';migrationDetail.innerHTML=icon('folder')+'<div><strong>Migration focus</strong><span id="week-migration-text"></span></div>';document.querySelector('.week-seo').after(migrationDetail);function syncMigration(i){document.querySelector('#week-migration-text').textContent=migrationWeeks[i]}document.addEventListener('proposal-week',e=>syncMigration(e.detail));syncMigration(selectedWeek);
const mobileMigration=['Inventory content, media and resources; agree scope, mappings and archive decisions.','Test a representative import and verify formatting, links, media and visibility.','Transfer approved content in batches; verify protected portal resources.','Complete approved batches and reconcile content relationships with editors.','Compare counts, check files and permissions, and resolve migration defects.','Run the agreed final sync / cutover, verify migrated journeys and confirm rollback readiness.'];document.querySelectorAll('.mobile-phase').forEach((card,i)=>{const label=document.createElement('div');label.className='mobile-migration';label.innerHTML=icon('folder')+'<div><strong>CONTENT MIGRATION</strong><span>'+mobileMigration[i]+'</span></div>';card.append(label)});document.querySelectorAll('.plan-label').forEach(label=>{if(/CONTENT MIGRATION|SEO & DISCOVERABILITY/.test(label.textContent))label.closest('.plan-lane')?.classList.add('priority-lane')});
